<?php
require dirname(__DIR__).'/includes/bootstrap.php';require APP_ROOT.'/services/thanh_toan.php';$me=require_role(['KHACH_HANG']);expire_holds();
handle_form(function()use($me){$id=post('id');transaction(function()use($me,$id){[$h,$x]=lock_contract($id);must((int)$h['tai_khoan_id']===(int)$me['id'],'Không có quyền.',403);must(!in_array($h['trang_thai_hd'],['HOAN_TAT','DA_HUY','HET_HAN'],true),'Đơn không còn phù hợp để hủy.');must(!db_one("SELECT 1 FROM yeu_cau_huy WHERE so_hop_dong=? AND trang_thai='CHO_DUYET'",[$id]),'Đã có yêu cầu hủy đang chờ.');execute('INSERT INTO yeu_cau_huy(so_hop_dong,khach_hang_id,ly_do) VALUES(?,?,?)',[$id,$me['id'],valid_text(post('ly_do'),2000)]);audit('YEU_CAU_HUY','hop_dong',$id);});},'khach_hang/don_mua.php?id='.rawurlencode(get('id')));
page_start('Đơn mua xe của bạn');$rows=db_all('SELECT * FROM hop_dong WHERE tai_khoan_id=? ORDER BY ngay_lap DESC LIMIT 200',[$me['id']]);table_start(['Hợp đồng','VIN','Giá trị','Trạng thái','']);foreach($rows as$r)echo '<tr><td>'.e($r['so_hop_dong']).'</td><td>'.e($r['so_khung_vin']).'</td><td>'.e(money($r['tong_gia_tri'])).'</td><td>'.badge($r['trang_thai_hd']).'</td><td><a href="'.e(url('khach_hang/don_mua.php?id='.$r['so_hop_dong'])).'">Chi tiết</a></td></tr>';table_end();
if(get('id')){$h=contract(get('id'),$me);$net=money_total($h['so_hop_dong']);echo '<div class="panel"><h2>'.e($h['so_hop_dong']).'</h2><p>VIN: '.e($h['so_khung_vin']).' · Hạn giữ: '.e($h['han_giu_vin']).'</p><p>Giá chốt: '.e(money($h['tong_gia_tri'])).' · Đã trả ròng: '.e(money($net)).' · Còn thiếu: '.e(money(max(0,(int)$h['tong_gia_tri']-$net))).'</p><p>Tiến độ: '.e($h['tien_do_giao_xe']?:'Đang tiếp nhận').'</p>';
if($h['trang_thai_hd']==='CHO_COC'&&strtotime($h['han_giu_vin'])>time()){token_form(url('thanh_toan/tao_vnpay.php'));field('so_hop_dong','',$h['so_hop_dong'],'hidden');echo '<button>Thanh toán cọc qua VNPay Sandbox</button></form>';}
table_start(['Mốc thanh toán','Mức lũy kế','Còn thiếu']);foreach(db_all('SELECT * FROM moc_thanh_toan WHERE so_hop_dong=? ORDER BY so_tien_luy_ke',[$h['so_hop_dong']])as$m)echo '<tr><td>'.e($m['ten_moc']).'</td><td>'.e(money($m['so_tien_luy_ke'])).'</td><td>'.e(money(max(0,(int)$m['so_tien_luy_ke']-$net))).'</td></tr>';table_end();
table_start(['Ngày','Khoản','Số tiền','Trạng thái','Biên lai']);foreach(db_all('SELECT * FROM hoa_don WHERE so_hop_dong=? ORDER BY ngay_thu DESC,ma_hoa_don',[$h['so_hop_dong']])as$p)echo '<tr><td>'.e($p['ngay_thu']).'</td><td>'.badge($p['loai_giao_dich']).' '.e($p['phuong_thuc_tt']).'</td><td>'.e(money($p['so_tien_thu'])).'</td><td>'.badge($p['trang_thai']).'</td><td>'.($p['trang_thai']==='SUCCESS'?'<a href="'.e(url('khach_hang/bien_lai.php?id='.$p['ma_hoa_don'])).'">Xem / in</a>':'').'</td></tr>';table_end();
if($h['trang_thai_hd']==='HOAN_TAT')echo '<a class="button" href="'.e(url('khach_hang/danh_gia.php?id='.$h['so_hop_dong'])).'">Đánh giá dịch vụ</a>';elseif(!in_array($h['trang_thai_hd'],['DA_HUY','HET_HAN'],true)){echo '<details><summary>Gửi yêu cầu hủy đơn</summary>';token_form();field('id','',$h['so_hop_dong'],'hidden');textarea('ly_do','Lý do');echo '<button class="danger">Gửi yêu cầu</button></form></details>';}
foreach(db_all('SELECT * FROM yeu_cau_huy WHERE so_hop_dong=? ORDER BY id DESC',[$h['so_hop_dong']])as$r)echo '<p>Yêu cầu hủy: '.badge($r['trang_thai']).' '.e($r['ket_qua']).($r['tien_duoc_hoan']!==null?' · Được hoàn: '.e(money($r['tien_duoc_hoan'])):'').'</p>';echo '</div>';}
page_end();
